def build_agent(sandbox):
    start_x = 10.0
    start_y = 2.5

    # Create torso
    torso = sandbox.add_beam(
        x=start_x, y=start_y, width=2.0, height=0.5, angle=0, density=2.0
    )
    sandbox.set_material_properties(torso, restitution=0.1, friction=1.0)

    # Create wheels
    wheel_radius = 0.5
    wheel_density = 1.0
    # Left wheel
    wheel1 = sandbox.add_wheel(x=start_x - 1.0, y=1.0 + wheel_radius, radius=wheel_radius, density=wheel_density)
    # Right wheel
    wheel2 = sandbox.add_wheel(x=start_x + 1.0, y=1.0 + wheel_radius, radius=wheel_radius, density=wheel_density)

    # Connect wheels to torso with pivot joints
    joint1 = sandbox.add_joint(torso, wheel1, (start_x - 1.0, start_y), type='pivot')
    joint2 = sandbox.add_joint(torso, wheel2, (start_x + 1.0, start_y), type='pivot')

    return {"body": torso, "joints": [joint1, joint2]}

def agent_action(sandbox, agent_body, step_count):
    joints = _get_joints(agent_body)
    torso = agent_body.get("body") if isinstance(agent_body, dict) else None
    if torso is not None:
        if torso.position.x > 28.0:
            rotation_speed = 0.0
        else:
            rotation_speed = -1.0  # Low speed to stay within joint limits
        for j in joints:
            sandbox.set_motor(j, rotation_speed, max_torque=2000.0)

